"""Build the local review page from final experiment artifacts."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).parent
TOPICS = [('evals', 'AI application evals', 'e01', 'e05'), ('causal', 'Causal inference', 'e03', 'e07'), ('encryption', 'Public-key encryption', 'e06', 'e02'), ('isolation', 'Database isolation', 'e08', 'e04')]
rows = []
for key, title, baseline, variant in TOPICS:
    rows.append(f'<tr><th scope="row">{title}</th><td><a href="runs/{baseline}/report.html">Baseline report</a></td><td><a href="runs/{variant}/report.html">DAG report</a></td><td><a href="runs/{variant}/dag.html">Graph</a> · <a href="runs/{variant}/dag.json">JSON</a></td></tr>')
summary_path = ROOT / 'review-summary.html'
summary = summary_path.read_text() if summary_path.exists() else '<p>Evaluation pending.</p>'
options = ''.join(f'<option value="{key}">{title}</option>' for key, title, _, _ in TOPICS)
data = json.dumps({key: {'baseline': b, 'variant': v} for key, _, b, v in TOPICS})
page = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Break It Down: DAG experiment</title><style>
:root{color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#f5f4f0;color:#101527;font:17px/1.65 system-ui,sans-serif}main{max-width:1440px;margin:auto;padding:40px 24px 80px}h1{font-size:clamp(2rem,4vw,3.5rem);line-height:1.1;letter-spacing:-.04em;margin:0 0 20px}h2{font-size:1.5rem;margin:36px 0 12px}p{max-width:850px}a{color:#2f6c9e;text-decoration:underline;font-weight:600}a:hover,a:focus{color:#bf3030}table{width:100%;border-collapse:collapse;margin:24px 0}th,td{border-bottom:1px solid #cbd0d3;text-align:left;padding:12px;vertical-align:top}th:first-child,td:first-child{padding-left:0}.table-wrap{overflow:auto}label{font-weight:600}select{font:inherit;margin:8px 12px;padding:8px;max-width:100%;background:white;border:1px solid #646c77}select:focus-visible,a:focus-visible{outline:3px solid #bf3030;outline-offset:3px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}.pair h3{font-size:1.1rem}iframe{width:100%;height:900px;border:1px solid #cbd0d3;background:white}.note{color:#646c77}code{font-size:.9em}li{max-width:1000px;margin:8px 0}@media(max-width:850px){main{padding:28px 20px}.pair{grid-template-columns:1fr}iframe{height:700px}th,td{padding:8px;font-size:15px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style></head><body><main><h1>Break It Down: DAG experiment</h1><p>Four topics. Eight independent generation agents. One separate evaluator. The current skill is preserved; the experimental variant adds prerequisite-driven research and saved concept graphs.</p>''' + summary + '''<h2>Reports and graphs</h2><div class="table-wrap"><table><thead><tr><th>Topic</th><th>Current skill</th><th>Experimental skill</th><th>Prerequisites</th></tr></thead><tbody>''' + ''.join(rows) + '''</tbody></table></div><h2>Read side by side</h2><label for="topic">Topic</label><select id="topic">''' + options + '''</select><p class="note">Each report scrolls independently. Use the links above for full-width reading.</p><div class="pair"><section><h3>Current skill</h3><iframe id="baseline" title="Current skill report" src="runs/e01/report.html"></iframe></section><section><h3>DAG variant</h3><iframe id="variant" title="DAG variant report" src="runs/e05/report.html"></iframe></section></div><h2>Audit trail</h2><p><a href="evaluation/report-evaluation.md">Blind report evaluation</a> · <a href="evaluation/graph-evaluation.md">Graph evaluation</a> · <a href="results.md">Results and limitations</a> · <a href="protocol.md">Frozen protocol</a> · <a href="skill-change.diff">Exact skill changes</a> · <a href="graph-checks.json">Graph checks</a> · <a href="scores-unblinded.json">Unblinded scores</a> · <a href="output-metrics.json">Output metrics</a> · <a href="validation.md">Validation</a></p><p><a href="inputs/baseline.txt">Frozen baseline instructions</a> · <a href="inputs/variant.txt">Frozen DAG instructions</a></p><p class="note">One output per condition and topic, one evaluator, no human comprehension testing. Scores describe this pilot; they do not establish a general improvement.</p></main><script>
const runs=''' + data + ''';document.getElementById('topic').addEventListener('change',e=>{for(const kind of ['baseline','variant'])document.getElementById(kind).src='runs/'+runs[e.target.value][kind]+'/report.html'});
</script></body></html>'''
(ROOT / 'index.html').write_text(page)
print(ROOT / 'index.html')
